    private static void convertToTriple() {
        rawMatrix.clear();
        for(int row = 0; row < rowNumber; row ++) {
            for(int col = 0; col < colNumber; col ++) {
                if(matrix[row][col] != 0) {
                    rawMatrix.add(new Triple(row, col, matrix[row][col]));
                }
            }
        }
        System.out.println("转化后的三元组为：");
        System.out.println("行\t列\t值");
        for(Triple triple : rawMatrix) {
            System.out.println(triple);
        }
    }

    private static void transposition() {
        targetMatrix.clear();
        for(int col = 0; col < colNumber; col ++) {         //按列扫描，保证结果按行有序
            for(Triple triple : rawMatrix) {
                if(triple.getCol() == col) {
                    targetMatrix.add(new Triple(triple.getCol(), triple.getRow(), triple.getNumber()));
                }
            }
        }
        Collections.sort(targetMatrix, new TripleComparator());
        System.out.println("转置后的三元组为：");
        System.out.println("行\t列\t值");
        for(Triple triple : targetMatrix) {
            System.out.println(triple);
        }
        System.out.println("转置后的矩阵为：");
        int index = 0;
        for(int row = 0; row < colNumber; row ++) {
            for(int col = 0; col < rowNumber; col ++) {
                if(index < targetMatrix.size() && targetMatrix.get(index).getRow() == row
                        && targetMatrix.get(index).getCol() == col) {
                    System.out.print(targetMatrix.get(index).getNumber() + "\t");
                    index ++;
                } else {
                    System.out.print(0 + "\t");
                }
            }
            System.out.println();
        }
    }
}

class TripleComparator implements Comparator<Triple> {
    public int compare(Triple triple1, Triple triple2) {
        if(triple1.getRow() != triple2.getRow()) {
            return triple1.getRow() - triple2.getRow();
        }
        return triple1.getCol() - triple2.getCol();
    }
}

