private static void quickTransposition() {
    int[] colCount = new int[colNumber];                //原矩阵每一列的非零元素个数
    int[] startPosition = new int[colNumber];           //转置后每一行在三元组表中的起始位置
    for(Triple triple : rawMatrix) {
        colCount[triple.getCol()] ++;
    }
    startPosition[0] = 0;
    for(int col = 1; col < colNumber; col ++) {
        startPosition[col] = startPosition[col - 1] + colCount[col - 1];
    }
    targetMatrix.clear();
    for(int i = 0; i < rawMatrix.size(); i ++) {         //占位，便于按下标直接放置
        targetMatrix.add(new Triple());
    }
    for(Triple triple : rawMatrix) {                     //一趟扫描完成转置
        int position = startPosition[triple.getCol()];
        targetMatrix.set(position, new Triple(triple.getCol(), triple.getRow(), triple.getNumber()));
        startPosition[triple.getCol()] ++;
    }
    System.out.println("转置后的三元组为：");
    System.out.println("行\t列\t值");
    for(Triple triple : targetMatrix) {
        System.out.println(triple);
    }
    System.out.println("转置后的矩阵为：");
    int index = 0;
    for(int row = 0; row < colNumber; row ++) {
        for(int col = 0; col < rowNumber; col ++) {
            if(index < targetMatrix.size() && targetMatrix.get(index).getRow() == row
                    && targetMatrix.get(index).getCol() == col) {
                System.out.print(targetMatrix.get(index).getNumber() + "\t");
                index ++;
            } else {
                System.out.print(0 + "\t");
            }
        }
        System.out.println();
    }
}

