private static void constructLinkedList() {
    int remainder = rawString.length() % 4;              //每个节点存放4个字符
    int nodeNumber = remainder == 0 ? rawString.length() / 4 : rawString.length() / 4 + 1;
    for(int i = 0; i < 4 - remainder; i ++) {             //补齐最后一个节点
        rawString = rawString + "\0";
    }
    headNode = new Node("");
    Node currentNode = headNode;
    for(int i = 0; i < nodeNumber; i ++) {
        currentNode.setNextNode(new Node(rawString.substring(i * 4, i * 4 + 4)));
        currentNode.getNextNode().setPreviousNode(currentNode);
        currentNode = currentNode.getNextNode();
    }
}

private static boolean matchString() {
    int index = 0;
    Node currentNode = headNode.getNextNode();
    Node matchNode = null;
    int matchIndex = 0;
    while(currentNode != null) {
        for(int i = 0; i < 4; i ++) {                    //在当前节点内逐个字符尝试匹配
            if(currentNode.getNodeString().charAt(i) == matchString.charAt(0)) {
                matchNode = currentNode;
                matchIndex = i;
                boolean matched = true;
                for(index = 0; index < matchString.length(); index ++) {
                    if(matchIndex >= 4) {                //跨节点继续匹配
                        matchNode = matchNode.getNextNode();
                        matchIndex = 0;
                    }
                    if(matchNode == null
                            || matchNode.getNodeString().charAt(matchIndex) != matchString.charAt(index)) {
                        matched = false;
                        break;
                    }
                    matchIndex ++;
                }
                if(matched) {
                    return true;
                }
            }
        }
        currentNode = currentNode.getNextNode();
    }
    return false;
}

